import { POOLS, getRating, poolFor } from './rating.js';
import { LEVELS } from './computer.js';
import { Chess } from 'chess.js';
import { createClient } from '@supabase/supabase-js';
import { initialState, applyCommand } from './domain.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={play:'<path d="m9 5 11 7-11 7z"/>',trophy:'<path d="M8 3h8v6a4 4 0 0 1-8 0zM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 13v7m-4 1h8"/>',wallet:'<path d="M20 8V5H5a3 3 0 0 0 0 6h15v10H5a3 3 0 0 1-3-3V8m18 5h-6v5h6m-3-3h1"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6zm-4 9 3 3 5-6"/>',chart:'<path d="M4 3v18h17M8 16v-5m5 5V7m5 9V4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 4c3 0 4 2 4 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.play}</svg>`;
const credits=n=>`${((n||0)/100).toLocaleString('pt-BR',{maximumFractionDigits:2})} cr`;
const label={open:'Aberto',matched:'Em jogo',registration:'Inscrições abertas',running:'Em andamento',finished:'Concluído',cancelled:'Cancelado',pending:'Aceite pendente',playing:'Em jogo',review:'Em homologação',active:'Ativa',suspended:'Suspensa',banned:'Banida'};
let config={},client,session,online=false,tab='lobby',state,actor={id:'demo-you',admin:false},selected=null,practice=null,gameId=null,filter='all',busy=false;
let computerWorker=null,thinking=false,boardFlipped=false,engineGeneration=0,lastPresence=0,queueMode='all',rankingPool='blitz';
function seed(){let s=initialState();const people=[['demo-you','Você',1200],['demo-luiza','Luiza R.',1320],['demo-pedro','Pedro M.',1180],['demo-ana','Ana C.',1410],['demo-admin','Administrador',1500]];for(const [uid,name,rating]of people){s=applyCommand(s,{id:uid,admin:false},{id:crypto.randomUUID(),type:'register',payload:{name}});s.players[uid].rating=rating;s=applyCommand(s,{id:uid},{id:crypto.randomUUID(),type:'demo_credit'});}for(const [uid,stake,minutes]of [['demo-luiza',1000,5],['demo-pedro',2000,3],['demo-ana',500,10]])s=applyCommand(s,{id:uid},{id:crypto.randomUUID(),type:'challenge_create',payload:{stake,minutes}});s=applyCommand(s,{id:'demo-admin',admin:true},{id:'demo-tournament',type:'tournament_create',payload:{name:'Copa de abertura',capacity:4,entry:1000,minutes:5,minRating:0,maxRating:2000,startsAt:Date.now()+86400000,requireVerified:false,cameraFinal:false}});return s;}
function loadDemo(){try{const saved=JSON.parse(localStorage.getItem('arena-demo-v1'));state=saved?.version===1?saved:seed();}catch{state=seed();}online=false;actor={id:'demo-you',admin:false};}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function api(command){const response=await fetch('/api/index'+(command?'':'?action=state'),{method:command?'POST':'GET',headers:{'Content-Type':'application/json',...(session?{Authorization:`Bearer ${session.access_token}`}:{})},...(command?{body:JSON.stringify(command)}:{})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Falha na conexão.');return data;}
async function send(type,payload={}){if(busy)return;if(config.configured&&!online&&!['register'].includes(type)){loginForm();return false;}busy=true;try{const command={id:crypto.randomUUID(),type,payload};if(online){const result=await api(command);state=result.state;actor=result.actor;}else{state=applyCommand(state,actor,command);localStorage.setItem('arena-demo-v1',JSON.stringify(state));}selected=null;render();return true;}catch(e){toast(e.message);return false;}finally{busy=false;}}
function name(uid){return esc(state.players[uid]?.name||'Jogador');}
function avatar(uid){const p=state.players[uid];return `<span class="avatar hue${(uid||'').length%4}">${esc((p?.name||'?').slice(0,1))}</span>`;}
function badge(text,type=''){return `<span class="badge ${type}">${esc(text)}</span>`;}
function modal(html){$('#modal').innerHTML=`<button class="close" data-close aria-label="Fechar">×</button>${html}`;$('#modal').showModal();}
function shell(){const me=state.players[actor?.id];$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#lobby"><img src="/icon.svg" alt="">arena<span>xadrez</span></a><div class="nav-label">SEU PRÓXIMO LANCE</div><nav>${[['lobby','play','Jogar'],['tournaments','trophy','Torneios'],['ranking','chart','Classificação'],['wallet','wallet','Carteira'],['fairplay','shield','Fair play'],...(actor?.admin?[['admin','users','Administração']]:[])].map(([v,i,t])=>`<button class="nav ${tab===v?'active':''}" data-tab="${v}">${icon(i)}<span>${t}</span>${v==='tournaments'?`<i aria-label="${tournamentCount()} campeonatos disponíveis">${tournamentCount()}</i>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="small-panel">${icon('shield')}<strong>Jogue com confiança.</strong><p>Regras claras.<br>Competição justa.</p><button class="text-btn" data-tab="fairplay">Conheça o fair play ↗</button></div><button class="profile" data-action="profile">${avatar(actor?.id)}<span><b>${me?name(actor.id):'Visitante'}</b><small>${online?'Conta online':config.configured?'Visitante · entre para jogar online':'Ambiente de demonstração'}</small></span><span>⋯</span></button></div></aside><main><header><div class="breadcrumb">Arena <span>/</span> ${esc({lobby:'Jogar',tournaments:'Torneios',ranking:'Classificação',wallet:'Carteira',fairplay:'Fair play',admin:'Administração',board:'Mesa de jogo'}[tab]||'Jogar')}</div><div class="header-right"><span class="status-dot"></span><span>${online?'Online · créditos de teste':config.configured?'Entre para jogar online':'Demonstração local'}</span><button class="balance" data-tab="wallet">${icon('wallet')}${credits(me?.available)}</button><button class="button small" data-action="${online?'logout':'login'}">${online?'Sair':'Entrar'}</button></div></header><div class="content" id="content"></div><footer>ARENA XADREZ <span>Ambiente de testes · créditos sem valor monetário · sem depósitos ou saques reais</span><a href="#fairplay">Regras e privacidade</a></footer></main><nav class="mobile-nav">${[['lobby','play','Jogar'],['tournaments','trophy','Torneios'],['wallet','wallet','Carteira'],['fairplay','shield','Fair play']].map(([v,i,t])=>`<button data-tab="${v}" class="${tab===v?'active':''}">${icon(i)}${t}${v==='tournaments'?` <b class="nav-count">${tournamentCount()}</b>`:''}</button>`).join('')}</nav>`;}
function miniBoard(){const board=new Chess();return `<div class="hero-board" aria-hidden="true">${board.board().flat().map((p,i)=>`<div class="mini-square ${(Math.floor(i/8)+i%8)%2?'dark':'light'}">${p?piece(p):''}</div>`).join('')}</div>`;}
const glyph={wk:'♚',wq:'♛',wr:'♜',wb:'♝',wn:'♞',wp:'♟',bk:'♚',bq:'♛',br:'♜',bb:'♝',bn:'♞',bp:'♟'};
function piece(p){return `<span class="piece ${p.color==='w'?'white-piece':'black-piece'}">${glyph[p.color+p.type]}</span>`;}
function lobby(){const offers=state.challenges.filter(c=>(queueMode==='all'||(queueMode==='free'?c.stake===0:c.stake>0))&&c.status==='open'&&(!c.expiresAt||c.expiresAt>Date.now())&&(filter==='all'||c.minutes===Number(filter)));return `${playModes()}<section class="hero"><div class="hero-copy"><div class="eyebrow"><span></span> PARA QUEM PENSA À FRENTE</div><h1>Seu talento.<br>Seu próximo <em>desafio.</em></h1><p>Encontre seu adversário, entre na mesa<br>e faça cada lance valer.</p><div class="hero-actions"><button class="button primary" data-action="create-challenge">${icon('plus')} Criar desafio</button><button class="button ghost" data-tab="tournaments">Explorar torneios ${icon('arrow')}</button></div><div class="hero-note">${icon('shield')} Valores e taxa visíveis antes do aceite</div></div><div class="hero-art">${miniBoard()}<div class="floating-tag">♞ <span>Uma boa partida<br><b>começa com você.</b></span></div></div></section><div class="stat-strip"><div>${icon('play')}<span><b>${state.challenges.filter(c=>c.status==='open'&&(!c.expiresAt||c.expiresAt>Date.now())).length}</b> desafios abertos</span></div><div>${icon('trophy')}<span><b>${state.tournaments.filter(t=>t.status==='registration').length}</b> torneios com inscrições</span></div><div>${icon('users')}<span><b>${Object.keys(state.players).length}</b> perfis ${config.configured?'cadastrados':'de demonstração'}</span></div><div>${icon('shield')}<span>Créditos <b>100% demonstrativos</b></span></div></div><section class="lobby-grid"><div><div class="section-heading"><div><div class="eyebrow">ESCOLHA SUA MESA</div><h2>Desafios abertos <span class="count">${offers.length}</span></h2></div><button class="text-btn" data-action="create-challenge">Criar desafio +</button></div><div class="filters queue-filters">${[['all','Todas as mesas'],['free','Grátis'],['stake','Com entrada · teste']].map(([v,t])=>`<button data-queue="${v}" class="${queueMode===v?'selected':''}">${t}</button>`).join('')}</div><div class="filters">${[['all','Todos'],[1,'Bullet · 1 min'],[3,'Blitz · 3 min'],[5,'Blitz · 5 min'],[10,'Rápido · 10 min']].map(([v,t])=>`<button data-filter="${v}" class="${String(filter)===String(v)?'selected':''}">${t}</button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>JOGADOR / RATING</th><th>RITMO</th><th>ENTRADA</th><th>PRÊMIO LÍQUIDO</th><th></th></tr></thead><tbody>${offers.length?offers.map(c=>`<tr><td><div class="player-cell">${avatar(c.creator)}<span><b>${name(c.creator)}</b><small>${Math.round(getRating(state.players[c.creator],poolFor(c.minutes,c.increment)).rating)} ${state.players[c.creator].ratingVerified?'· Verificado':'· Não verificado'}</small></span></div></td><td><span class="time-pill">${icon('clock')}${c.minutes} + ${c.increment||0}</span></td><td><b>${c.stake===0?'Grátis':credits(c.stake)}</b></td><td class="prize">${credits(c.stake*2-Math.floor(c.stake*2*c.feeBps/10000))}<small>Taxa ${c.feeBps/100}%</small></td><td><button class="button outline small" data-action="${c.creator===actor?.id?'cancel-challenge':'accept-challenge'}" data-id="${c.id}">${c.creator===actor?.id?'Cancelar':'Aceitar'} ${icon('arrow')}</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">Nenhum desafio neste ritmo. Crie a próxima mesa.</td></tr>'}</tbody></table></div><div class="table-note">${icon('shield')} O saldo fica reservado até a homologação do resultado.</div>${myGames()}</div><aside class="right-rail"><div class="tournament-promo"><div class="promo-top">${icon('trophy')}${badge('INSCRIÇÕES ABERTAS','green')}</div><div class="eyebrow">SEU PRÓXIMO TROFÉU</div><h3>A competição<br>começa aqui.</h3><p>Enfrente jogadores da sua faixa e avance até a grande final.</p><div class="promo-line"><span>Formato</span><b>Mata-mata</b></div><div class="promo-line"><span>Empate</span><b>Revanche</b></div><button class="button primary" data-tab="tournaments">Ver torneios ${icon('arrow')}</button></div><button class="practice-card" data-action="practice"><span class="practice-knight">♞</span><span><b>Aqueça seu jogo</b><small>Tabuleiro livre no mesmo aparelho</small></span>${icon('arrow')}</button></aside></section>`;}
function myGames(){const games=state.games.filter(g=>[g.white,g.black].includes(actor?.id));return games.length?`<section class="my-games"><h2>Meus confrontos</h2>${games.slice().reverse().map(g=>`<button class="game-row" data-game="${g.id}"><span>${name(g.white)} <small>×</small> ${name(g.black)}</span>${badge(label[g.status])}<span>Abrir mesa →</span></button>`).join('')}</section>`:'';}
function tournaments(){return `<div class="page-heading"><div><div class="eyebrow">AVANCE A CADA VITÓRIA</div><h1>Torneios da Arena</h1><p>Inscreva-se, aceite o confronto e conquiste seu lugar na final.</p></div>${actor?.admin?'<button class="button primary" data-action="create-tournament">+ Criar torneio</button>':''}</div><div class="tournament-grid">${state.tournaments.map(t=>`<article class="tournament-card"><div class="tournament-card-head">${icon('trophy')}${badge(label[t.status],'green')}</div><h2>${esc(t.name)}</h2><p>${new Date(t.startsAt).toLocaleString('pt-BR')} · ${t.minutes} + 0</p><div class="card-stats"><div><small>INSCRIÇÃO</small><b>${credits(t.entry)}</b></div><div><small>PRÊMIO ATUAL</small><b class="prize">${credits(t.entry*t.players.length-Math.floor(t.entry*t.players.length*t.feeBps/10000))}</b></div></div><div class="capacity"><span style="width:${t.players.length/t.capacity*100}%"></span></div><div class="promo-line"><span>${t.players.length}/${t.capacity} inscritos</span><span>Rating ${t.minRating}–${t.maxRating}</span></div><p class="muted">Taxa ${t.feeBps/100}% · ${t.requireVerified?'Rating verificado obrigatório':'Rating não verificado permitido'}${t.cameraFinal?' · Câmera obrigatória na final (infraestrutura pendente)':''}</p>${t.status==='registration'?`<button class="button ${t.players.includes(actor?.id)?'outline':'primary'} full" data-action="${t.players.includes(actor?.id)?'leave-tournament':'join-tournament'}" data-id="${t.id}">${t.players.includes(actor?.id)?'Cancelar inscrição':'Participar do torneio'}</button>`:t.winner?`<p>Campeão: <b>${name(t.winner)}</b></p>`:''}${actor?.admin&&t.status==='registration'?`<div class="button-row"><button class="button small" data-action="start-tournament" data-id="${t.id}">Iniciar torneio</button><button class="text-btn" data-action="cancel-tournament" data-id="${t.id}">Cancelar</button></div>`:''}<div class="bracket">${state.games.filter(g=>g.tournament===t.id).map(g=>`<button data-game="${g.id}"><small>Rodada ${g.round} · ${label[g.status]}</small>${name(g.white)} × ${name(g.black)}${g.winner?' → '+name(g.winner):''}</button>`).join('')}</div></article>`).join('')||'<div class="empty panel">Ainda não há torneios cadastrados.</div>'}</div>${myGames()}`;}
function wallet(){const me=state.players[actor?.id];return `<div class="page-heading"><div><div class="eyebrow">CONTROLE EM CADA MOVIMENTO</div><h1>Sua carteira</h1><button class="button outline small" data-action="profile">Perfil e contas de teste</button><p>Créditos de teste. Sem valor monetário, depósitos ou saques reais.</p></div></div><div class="wallet-cards"><article class="panel"><small>SALDO DISPONÍVEL</small><h2>${credits(me?.available)}</h2><button class="button primary" data-action="demo-credit">Receber 100 créditos de teste</button></article><article class="panel"><small>SALDO RESERVADO</small><h2>${credits(me?.reserved)}</h2><p>Comprometido em desafios e torneios.</p></article><article class="panel"><small>COMO FUNCIONA</small><p>O aceite reserva os valores dos dois jogadores. A homologação libera o prêmio com a taxa combinada no desafio.</p></article></div><h2>Extrato</h2><div class="table-wrap"><table><thead><tr><th>DATA</th><th>OPERAÇÃO</th><th>DISPONÍVEL</th><th>RESERVADO</th></tr></thead><tbody>${state.ledger.filter(e=>e.user===actor?.id).slice().reverse().map(e=>`<tr><td>${new Date(e.at).toLocaleString('pt-BR')}</td><td>${esc({demo_credit:'Créditos de demonstração',challenge_hold:'Reserva de desafio',challenge_release:'Devolução de desafio',match_settlement:'Liquidação de confronto',match_prize:'Prêmio de confronto',tournament_hold:'Inscrição em torneio',tournament_release:'Devolução de inscrição',tournament_settlement:'Liquidação de torneio',tournament_prize:'Prêmio de torneio'}[e.type]||e.type)}</td><td>${e.available>0?'+':''}${credits(e.available)}</td><td>${e.reserved>0?'+':''}${credits(e.reserved)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Entre na conta para ver seu extrato.</td></tr>'}</tbody></table></div>`;}
function tournamentCount(){return state.tournaments.filter(t=>t.status==='running'||t.status==='registration'&&t.startsAt>Date.now()).length;}
function ranking(){const players=Object.values(state.players).sort((a,b)=>getRating(b,rankingPool).rating-getRating(a,rankingPool).rating);return `<div class="page-heading"><div><div class="eyebrow">CADA LANCE CONTA</div><h1>Classificação</h1><p>Glicko-2 por ritmo: bullet, blitz, rápido e clássico. Rating provisório nas primeiras 10 partidas ou com incerteza alta. Resultados com entrada contam após homologação; treinos não alteram rating.</p></div></div><div class="filters">${POOLS.map(pool=>`<button data-pool="${pool}" class="${rankingPool===pool?'selected':''}">${{bullet:'Bullet',blitz:'Blitz',rapid:'Rápido',classical:'Clássico'}[pool]}</button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>POSIÇÃO</th><th>JOGADOR</th><th>RATING</th><th>PARTIDAS</th><th>VITÓRIAS</th><th>DERROTAS</th></tr></thead><tbody>${players.map((p,i)=>{const r=getRating(p,rankingPool);return `<tr><td>#${i+1}</td><td><div class="player-cell">${avatar(p.id)}${esc(p.name)}</div></td><td><b>${Math.round(r.rating)}${r.games<10||r.deviation>110?' ?':''}</b><small>Incerteza ±${Math.round(r.deviation)}</small></td><td>${r.games}</td><td>${r.wins}</td><td>${r.losses}</td></tr>`;}).join('')}</tbody></table></div>${state.players[actor?.id]?.ratingHistory?.length?`<h2>Seu histórico recente</h2><div class="panel">${state.players[actor.id].ratingHistory.filter(h=>h.pool===rankingPool).slice(-15).reverse().map(h=>`<div class="promo-line"><span>${new Date(h.at).toLocaleString('pt-BR')}</span><b>${Math.round(h.rating)} (${h.change>0?'+':''}${h.change})</b></div>`).join('')||'Sem partidas neste ritmo.'}</div>`:''}`;}
function fairplay(){return `<div class="page-heading"><div><div class="eyebrow">O RESPEITO TAMBÉM FAZ PARTE DO JOGO</div><h1>Uma Arena mais justa.</h1><p>Proteções transparentes, decisões registradas e direito à revisão.</p></div></div><div class="info-grid">${[['shield','Assistência externa é proibida','É proibido receber lances de engines, extensões, outros jogadores ou dispositivos durante uma partida.'],['chart','Rating e identidade','Torneios podem exigir histórico de rating verificado pela administração. CPF e titularidade Pix dependerão do provedor de identidade e pagamentos; ainda não estão integrados.'],['users','Revisão antes do prêmio','Resultados aguardam homologação. Denúncias e decisões administrativas são registradas. Contas suspensas ou banidas podem ser reativadas pelo administrador com justificativa.'],['play','Stockfish é evidência, não veredito','A análise deve ocorrer em infraestrutura privada. A coincidência de lances não prova trapaça. O administrador pode ativar a análise privada de lances no servidor. O uso da engine no treino é independente desta análise.'],['clock','Empate gera revanche','Os valores permanecem reservados. As cores são invertidas e ambos aceitam a nova partida antes de o relógio começar.'],['shield','Limites das proteções','A aplicação não impede fotos com outro celular, engines externas nem todas as extensões. Ocultar o tabuleiro ao sair da tela é opcional e não é prova de fraude.']].map(([i,t,p])=>`<article class="panel">${icon(i)}<h2>${t}</h2><p>${p}</p></article>`).join('')}</div><article class="panel legal"><h2>Regras e privacidade desta demonstração</h2><p>Créditos são fictícios, não podem ser comprados, transferidos ou convertidos em dinheiro. A demonstração local armazena partidas somente neste navegador. O modo online usa autenticação e armazenamento Supabase. Não envie CPF, documentos ou dados bancários nesta versão.</p><p>Não há captura de câmera, microfone ou tela. Competições que exigem fiscalização por câmera não podem ser iniciadas nesta versão. O uso com dinheiro real e a publicação na Google Play dependem de avaliação própria e dos requisitos de cada serviço.</p><button class="button outline" data-action="reset-demo">Apagar dados locais de demonstração</button></article>`;}
function administration(){return `<div class="page-heading"><div><div class="eyebrow">CONTROLE DA ARENA</div><h1>Administração</h1><p>${online?'Acesso verificado pelo servidor.':'Simulador administrativo local. Não altera contas reais.'}</p></div></div><div class="admin-grid"><form id="settings-form" class="panel"><h2>Taxas e análise</h2><label>Taxa da plataforma (%)<input type="number" name="fee" min="0" max="30" step="0.1" value="${state.settings.feeBps/100}" required></label><label class="check"><input type="checkbox" name="analysis" ${state.settings.analysisEnabled?'checked':''}> Ativar análise privada Stockfish a cada lance</label><p class="muted">A análise ocorre no servidor após os lances. É evidência para revisão humana e não causa banimento automático. Não mostra sugestões aos jogadores.</p><button class="button primary">Salvar configuração</button></form><article class="panel"><h2>Integrações</h2>${[['Supabase',online?'Conectado':'Pendente — organização nova'],['Pagamentos Pix','Não integrado'],['Lichess OAuth / partidas','Não integrado'],['Stockfish privado',config.analysisWorkerConfigured?'Integrado · '+(state.settings.analysisEnabled?'ativado':'desativado pelo admin'):'Indisponível'],['Identidade / CPF','Não integrado'],['Câmera / fiscalização','Não integrado'],['Dinheiro real','Desativado']].map(([a,b])=>`<div class="promo-line"><span>${a}</span>${badge(b)}</div>`).join('')}</article></div><h2>Análises privadas</h2><div class="panel"><p>${state.games.reduce((n,g)=>n+(g.analysis||[]).filter(a=>a.status==='pending').length,0)} pendentes · ${state.games.reduce((n,g)=>n+(g.analysis||[]).filter(a=>a.status==='complete').length,0)} concluídas · ${state.games.reduce((n,g)=>n+(g.analysis||[]).filter(a=>a.status==='error').length,0)} com falha</p><button class="button outline small" data-action="analysis-retry">Reprocessar falhas</button>${state.games.filter(g=>g.fairPlay).map(g=>`<p>Mesa ${esc(g.id.slice(0,8))}: ${Object.entries(g.fairPlay).map(([u,r])=>`${name(u)} · ${r.positions} posições · ${r.engineMatches} coincidências · perda média ${r.averageLoss} cp`).join(' / ')}</p>`).join('')}<small>Coincidência de lances não prova trapaça. Revise contexto e histórico antes de restringir uma conta.</small></div><h2>Jogadores</h2><div class="table-wrap"><table><thead><tr><th>JOGADOR</th><th>RATING</th><th>CONTA</th><th>AÇÕES</th></tr></thead><tbody>${Object.values(state.players).map(p=>`<tr><td>${esc(p.name)}</td><td>${p.rating} ${p.ratingVerified?'✓':''}</td><td>${badge(label[p.status])}</td><td><button class="text-btn" data-action="verify-rating" data-id="${p.id}">Verificar rating</button> <button class="text-btn" data-action="account-status" data-id="${p.id}">Alterar status</button></td></tr>`).join('')}</tbody></table></div><h2>Resultados e denúncias</h2>${state.games.filter(g=>g.status==='review').map(g=>`<div class="game-row"><span>${name(g.white)} × ${name(g.black)}<small>Vencedor: ${name(g.winner)} · ${g.reason}</small></span><button class="button small" data-game="${g.id}">Ver partida</button><button class="button primary small" data-action="approve-result" data-id="${g.id}">Homologar</button></div>`).join('')||'<div class="panel muted">Nenhum resultado aguardando homologação.</div>'}${state.reviews.filter(r=>r.type==='report'&&r.status==='open').map(r=>`<div class="panel"><b>Denúncia: ${name(r.user)}</b><p>${esc(r.reason)}</p><button class="button outline" data-action="close-review" data-id="${r.id}">Concluir revisão</button></div>`).join('')}<h2>Auditoria</h2><div class="panel audit">${state.audit.slice(-30).reverse().map(a=>`<div><small>${new Date(a.at).toLocaleString('pt-BR')}</small><b>${esc(a.action)}</b><code>${esc(JSON.stringify(a.detail))}</code></div>`).join('')||'Nenhuma decisão administrativa registrada.'}</div>`;}
function activeGame(){return practice||state.games.find(g=>g.id===gameId);}
function boardView(){const g=activeGame();if(!g)return '<div class="empty">Partida não encontrada.</div>';const chess=new Chess(g.fen),own=g.white===actor?.id||g.black===actor?.id;const flip=boardFlipped!==Boolean(practice?g.computer&&g.humanColor==='b':g.black===actor?.id);const ranks=flip?[1,2,3,4,5,6,7,8]:[8,7,6,5,4,3,2,1],files=flip?'hgfedcba':'abcdefgh';const legal=selected?chess.moves({square:selected,verbose:true}).map(m=>m.to):[];return `<div class="board-heading"><div><div class="eyebrow">${practice?(g.computer?'CONTRA O COMPUTADOR · NÍVEL '+g.level:'TABULEIRO LIVRE · MESMO APARELHO'):'MESA '+esc(g.id.slice(0,8))}</div><h2>${practice?(g.computer?'Computador · '+LEVELS[g.level-1].name:'Aqueça seu jogo'):name(g.white)+' × '+name(g.black)}</h2></div><button class="button outline" data-tab="lobby">Voltar ao lobby</button></div><div class="board-layout"><section><div class="board-player">${avatar(flip?g.white:g.black)}<b>${practice?(g.computer?(g.humanColor===(flip?'w':'b')?'Você':'Computador'):'Peças pretas'):name(flip?g.white:g.black)}</b><span class="clock" id="clock-top" data-color="${flip?'w':'b'}"></span></div><div class="board" role="group" aria-label="Tabuleiro de xadrez">${ranks.map(rank=>[...files].map((file,i)=>{const square=file+rank,p=chess.get(square);return `<button class="square ${(file.charCodeAt(0)-97+rank)%2?'light':'dark'} ${selected===square?'picked':''} ${legal.includes(square)?'legal':''}" data-square="${square}" aria-label="${square}${p?' '+p.color+p.type:''}">${p?piece(p):''}${i===0?`<small class="rank-label">${rank}</small>`:''}${rank===ranks[7]?`<small class="file-label">${file}</small>`:''}</button>`;}).join('')).join('')}</div><div class="board-player">${avatar(flip?g.black:g.white)}<b>${practice?(g.computer?(g.humanColor===(flip?'b':'w')?'Você':'Computador'):'Peças brancas'):name(flip?g.black:g.white)}</b><span class="clock" id="clock-bottom" data-color="${flip?'b':'w'}"></span></div></section><aside class="board-side"><article class="panel">${badge(practice?(g.computer?'Treino contra o computador':'Treino livre'):label[g.status],'green')}<h3>${practice&&g.status==='finished'?esc(g.result):thinking?'Computador pensando…':chess.isCheck()?'Xeque!':g.status==='playing'?(chess.turn()==='w'?'Brancas':'Pretas')+' jogam':g.status==='pending'?'Aguardando jogadores':g.status==='review'?'Resultado em homologação':'Partida concluída'}</h3>${!practice?`<div class="promo-line"><span>Total na mesa</span><b>${credits(g.stake*2)}</b></div><div class="promo-line"><span>Taxa acordada</span><b>${g.feeBps/100}%</b></div>${g.tournament?'<p class="muted">A premiação pertence ao torneio. Não há cobrança por rodada.</p>':''}${g.rematches?`<p>Revanche ${g.rematches} · cores invertidas</p>`:''}${g.winner?`<p>Vencedor: <b>${name(g.winner)}</b></p>`:''}${g.status==='pending'&&own?`<p>${g.accepted.map(name).join(', ')||'Nenhum jogador'} confirmou.</p><button class="button primary full" data-action="game-accept" data-id="${g.id}" ${g.accepted.includes(actor.id)?'disabled':''}>${g.accepted.includes(actor.id)?'Aguardando adversário':'Aceitar e abrir partida'}</button>${g.challenge&&Date.now()-g.createdAt>90000?`<button class="text-btn" data-action="game-abort" data-id="${g.id}">Cancelar por ausência</button>`:''}`:''}${!online&&g.status!=='finished'?`<button class="button outline full" data-action="switch-seat">Alternar jogador de teste</button><small class="muted">Simulação no mesmo navegador; não é um adversário online.</small>`:''}${g.status==='playing'&&own?`<button class="button outline small" data-action="claim-timeout" data-id="${g.id}">Reivindicar tempo esgotado</button><div class="button-row"><button class="button outline small" data-action="draw" data-id="${g.id}">${g.drawOffer&&g.drawOffer!==actor.id?'Aceitar empate':'Propor empate'}</button><button class="button danger small" data-action="resign" data-id="${g.id}">Desistir</button></div><button class="text-btn" data-action="report" data-id="${g.id}">Denunciar partida</button>`:''}`:`<p>${g.computer?'Você joga de '+(g.humanColor==='w'?'brancas':'pretas')+'. Nível '+g.level+' de 8. Sem apostas e sem alteração de rating.':'Jogue com as duas cores neste aparelho.'}</p><div class="button-row"><button class="button outline small" data-action="undo">Voltar lance</button><button class="button outline small" data-action="${g.computer?'computer':'practice'}">Nova partida</button></div>${g.computer&&g.status==='playing'?'<button class="text-btn" data-action="computer-resign">Desistir do treino</button>':''}`}</article><article class="panel"><h3>Lances</h3><button class="text-btn" data-action="flip-board">Girar tabuleiro ↻</button><div class="moves">${g.moves.map((m,i)=>`${i%2===0?`<small>${Math.floor(i/2)+1}.</small>`:''}<span>${esc(m)}</span>`).join('')||'<p class="muted">Aguardando o primeiro lance.</p>'}</div><button class="text-btn" data-action="export-pgn">Baixar PGN ↓</button></article><label class="check privacy"><input type="checkbox" id="privacy-toggle"> Ocultar tabuleiro ao sair da tela</label></aside></div>`;}
function render(){shell();$('#content').innerHTML=({lobby,tournaments,wallet,ranking,fairplay,admin:administration,board:boardView}[tab]||lobby)();updateClocks();}
function challengeForm(){modal(`<div class="eyebrow">UMA NOVA PARTIDA</div><h2>Criar desafio</h2><p>Entrada 0 cria uma partida casual grátis. Valores maiores usam apenas créditos de teste.</p><form id="challenge-form"><label>Entrada por jogador (créditos)<input name="stake" type="number" min="0" max="1000" step="1" value="10" required></label><label>Tempo por jogador<select name="minutes"><option value="1">1 minuto</option><option value="3">3 minutos</option><option value="5" selected>5 minutos</option><option value="10">10 minutos</option><option value="15">15 minutos</option></select></label><label>Incremento por lance<select name="increment">${[0,1,2,3,5,10,15,30].map(n=>`<option value="${n}">${n} segundos</option>`).join('')}</select></label><p class="muted">Taxa: ${state.settings.feeBps/100}%. Empate inicia revanche com o saldo reservado.</p><button class="button primary full">Criar e reservar entrada</button></form>`);}
function tournamentForm(){modal(`<h2>Novo torneio</h2><form id="tournament-form"><label>Nome<input name="name" minlength="3" maxlength="80" required></label><div class="form-grid"><label>Vagas<select name="capacity">${[2,4,8,16,32].map(n=>`<option>${n}</option>`).join('')}</select></label><label>Inscrição (créditos)<input name="entry" type="number" min="0" max="1000" value="10" required></label><label>Rating mínimo<input name="minRating" type="number" min="0" max="3500" value="0" required></label><label>Rating máximo<input name="maxRating" type="number" min="0" max="3500" value="2000" required></label></div><label>Início<input name="startsAt" type="datetime-local" required></label><label>Tempo<select name="minutes">${[1,3,5,10,15].map(n=>`<option value="${n}" ${n===5?'selected':''}>${n} minutos</option>`).join('')}</select></label><label class="check"><input name="verified" type="checkbox"> Exigir rating verificado</label><label class="check"><input name="camera" type="checkbox"> Exigir câmera na final (bloqueia início sem integração)</label><button class="button primary full">Criar mata-mata</button></form>`);}
function loginForm(){modal(`<h2>Entre na Arena</h2><p>Conta online ${config.configured?'com Supabase.':'aguardando configuração do Supabase.'}</p><form id="login-form"><label>Nome público<input name="name" maxlength="32" value="Jogador" required></label><label>E-mail<input name="email" type="email" required autocomplete="email"></label><label>Senha<input name="password" type="password" minlength="10" required autocomplete="current-password"></label><button name="intent" value="login" class="button primary full" ${config.configured?'':'disabled'}>Entrar</button><button name="intent" value="signup" class="button outline full" ${config.configured?'':'disabled'}>Criar conta</button><p id="auth-error" class="auth-error" role="alert"></p></form><button class="text-btn" data-action="resend-email">Reenviar confirmação de e-mail</button><p class="muted">${config.configured?'Confirme seu e-mail antes de jogar.':'Enquanto isso, a demonstração permite testar partidas e torneios neste aparelho.'}</p>`);}
function playModes(){return `<section class="play-modes" aria-label="Modos de jogo"><button class="mode-card" data-action="quick-match">${icon('users')}<span><b>Jogar online</b><small>Encontre um adversário · grátis</small></span>${icon('arrow')}</button><button class="mode-card" data-action="computer">${icon('play')}<span><b>Contra o computador</b><small>8 níveis · escolha sua cor e ritmo</small></span>${icon('arrow')}</button><button class="mode-card" data-action="quick-match" data-mode="stake">${icon('wallet')}<span><b>Jogar com entrada</b><small>Busca separada · créditos de teste</small></span>${icon('arrow')}</button>${localStorage.getItem('arena-computer-v1')?'<button class="button outline" data-action="resume-computer">Retomar treino</button>':''}</section>`;}
function quickMatchForm(mode='free'){if(!online&&config.configured)return loginForm();modal(`<h2>${mode==='stake'?'Buscar adversário · com entrada':'Jogar online · grátis'}</h2><p>Encontre outro jogador da Arena. Ambos confirmam antes de o relógio começar. ${mode==='stake'?'Os dois jogadores entram com o mesmo valor. Nesta versão são créditos de teste, sem conversão em reais.':'Sem entrada ou premiação.'}</p><form id="quick-form"><input type="hidden" name="mode" value="${mode}">${mode==='stake'?'<label>Entrada por jogador (créditos de teste)<input name="stake" type="number" min="1" max="1000" value="10" required></label><p>Dinheiro real ainda indisponível. Nenhum Pix será cobrado.</p>':''}<label>Tempo por jogador<select name="minutes">${[1,2,3,5,10,15,30].map(n=>`<option value="${n}" ${n===5?'selected':''}>${n} minutos</option>`).join('')}</select></label><label>Incremento por lance<select name="increment">${[0,1,2,3,5,10,15,30].map(n=>`<option>${n}</option>`).join('')}</select></label><button class="button primary full">Buscar adversário</button></form>`);}
function computerForm(){modal(`<h2>Jogar contra o computador</h2><p>Treine sem conta e sem apostas. A dificuldade aumenta com a busca e a precisão; os níveis não equivalem a um rating Elo oficial.</p><form id="computer-form"><label>Dificuldade<select name="level">${LEVELS.map((l,i)=>`<option value="${i+1}" ${i===2?'selected':''}>Nível ${i+1} · ${l.name}</option>`).join('')}</select></label><label>Suas peças<select name="color"><option value="w">Brancas</option><option value="b">Pretas</option><option value="random">Aleatórias</option></select></label><label>Tempo por jogador<select name="minutes"><option value="0">Sem relógio</option>${[1,3,5,10,15,30].map(n=>`<option value="${n}">${n} minutos</option>`).join('')}</select></label><label>Incremento por lance<select name="increment">${[0,1,2,3,5,10].map(n=>`<option>${n}</option>`).join('')}</select></label><button class="button primary full">Começar partida</button></form>`);}
function startComputer(d){cancelComputer();boardFlipped=false;const color=d.get('color'),minutes=Number(d.get('minutes'));practice={computer:true,level:Number(d.get('level')),humanColor:color==='random'?(Math.random()<.5?'w':'b'):color,fen:new Chess().fen(),moves:[],pgn:'',status:'playing',white:'demo-you',black:'demo-you',minutes,increment:Number(d.get('increment')),whiteMs:minutes*60000,blackMs:minutes*60000,lastMoveAt:Date.now()};selected=null;tab='board';savePractice();render();computerTurn();}
function authMessage(error){return ({email_not_confirmed:'Confirme seu e-mail antes de entrar. Procure a mensagem de confirmação na caixa de entrada ou no spam.',invalid_credentials:'E-mail ou senha incorretos.',over_email_send_rate_limit:'Aguarde alguns minutos antes de solicitar outro e-mail.',user_already_exists:'Esta conta já existe. Confirme seu e-mail e clique em Entrar.',email_address_not_authorized:'O serviço de e-mail ainda está em configuração. Entre em contato com a administração.'})[error.code]||'Não foi possível concluir. '+error.message;}
function confirmationNotice(email){modal(`<div class="eyebrow">FALTA SÓ UM PASSO</div><h2>Confirme seu e-mail</h2><p>Enviamos um link de confirmação para <strong>${esc(email)}</strong>.</p><p>Abra a mensagem, clique em <strong>Confirmar e-mail</strong> e volte à Arena para entrar. No e-mail padrão, o botão pode aparecer como <strong>Confirm your email address</strong>.</p><div class="panel"><b>Não encontrou?</b><p>Confira as pastas Spam e Promoções. O remetente atual é Supabase Auth. Não é necessário cadastrar novamente.</p></div><button class="button primary full" data-action="back-login">Já confirmei · entrar</button><button class="text-btn" data-action="resend-email">Reenviar confirmação</button>`);sessionStorage.setItem('arena-confirm-email',email);}
async function resendEmail(){if(!client)return;const email=$('#login-form input[name="email"]')?.value||sessionStorage.getItem('arena-confirm-email');if(!email)return toast('Informe seu e-mail no formulário antes de solicitar o reenvio.');const {error}=await client.auth.resend({type:'signup',email,options:{emailRedirectTo:location.origin+'/'}});if(error)return toast(authMessage(error));confirmationNotice(email);toast('Solicitação enviada. Confira também a pasta de spam.');}
async function squareClick(square){const g=activeGame();if(!g||g.status!=='playing'||(practice?.computer&&(thinking||new Chess(g.fen).turn()!==g.humanColor)))return;const chess=new Chess(g.fen);if(selected===square){selected=null;render();return;}if(selected){const moves=chess.moves({square:selected,verbose:true}).filter(m=>m.to===square);if(moves.length){if(moves.some(m=>m.promotion)){modal(`<h2>Promover peão</h2><div class="promotion">${['q','r','b','n'].map(p=>`<button data-promote="${p}" data-from="${selected}" data-to="${square}">${piece({color:chess.turn(),type:p})}</button>`).join('')}</div>`);return;}return playMove(selected,square);}}const p=chess.get(square);selected=p?.color===chess.turn()?square:null;render();}
function savePractice(){if(practice?.computer)localStorage.setItem('arena-computer-v1',JSON.stringify(practice));}
function finishPractice(c){if(c.isGameOver()){practice.status='finished';practice.result=c.isCheckmate()?(c.turn()===practice.humanColor?'Xeque-mate · Computador venceu':'Xeque-mate · Você venceu!'):'Empate · inicie uma nova partida';}}
function commitPracticeMove(move){const c=new Chess();for(const m of practice.moves)c.move(m);if(practice.minutes){const color=c.turn(),key=color==='w'?'whiteMs':'blackMs';practice[key]-=Math.max(0,Date.now()-practice.lastMoveAt);if(practice[key]<=0){practice.status='finished';practice.result='Tempo esgotado · '+(color===practice.humanColor?'Computador venceu':'Você venceu');savePractice();render();return;}practice[key]+=(practice.increment||0)*1000;}const m=c.move(move);practice.moves.push(m.san);practice.fen=c.fen();practice.pgn=c.pgn();practice.lastMoveAt=Date.now();selected=null;finishPractice(c);savePractice();render();}
function cancelComputer(){engineGeneration++;thinking=false;computerWorker?.terminate();computerWorker=null;}
function computerTurn(){if(!practice?.computer||practice.status!=='playing'||new Chess(practice.fen).turn()===practice.humanColor||thinking)return;thinking=true;const id=++engineGeneration;try{computerWorker??=new Worker('/computer-worker.js',{type:'module'});computerWorker.onmessage=e=>{if(e.data.id!==engineGeneration||!practice?.computer)return;thinking=false;if(e.data.error){toast(e.data.error);render();return;}try{commitPracticeMove(e.data.move);}catch{toast('Não foi possível executar o lance do computador.');}};computerWorker.onerror=()=>{cancelComputer();toast('Não foi possível iniciar o computador. Tente novamente.');render();};computerWorker.postMessage({id,fen:practice.fen,level:practice.level});render();}catch{cancelComputer();toast('Este navegador não conseguiu iniciar o computador.');}}
async function playMove(from,to,promotion='q'){if(practice){try{commitPracticeMove({from,to,promotion});computerTurn();}catch{toast('Lance inválido.');}}else await send('move',{id:gameId,from,to,promotion,ply:activeGame().moves.length});}
function updateClocks(){if(tab!=='board')return;const g=activeGame();if(!g)return;if(practice?.computer&&g.minutes&&g.status==='playing'){const color=new Chess(g.fen).turn();if(g[color==='w'?'whiteMs':'blackMs']-(Date.now()-g.lastMoveAt)<=0){cancelComputer();g.status='finished';g.result='Tempo esgotado · '+(color===g.humanColor?'Computador venceu':'Você venceu');savePractice();render();return;}}let turn=new Chess(g.fen).turn();for(const el of document.querySelectorAll('[data-color]')){const color=el.dataset.color;let ms=g[color==='w'?'whiteMs':'blackMs'];if((!practice||g.minutes)&&g.status==='playing'&&turn===color)ms-=Math.max(0,Date.now()-g.lastMoveAt);ms=Math.max(0,ms);el.textContent=practice&&!g.minutes?'∞':`${Math.floor(ms/60000).toString().padStart(2,'0')}:${Math.floor(ms%60000/1000).toString().padStart(2,'0')}`;el.classList.toggle('ticking',g.status==='playing'&&turn===color);}}
document.addEventListener('click',async e=>{const button=e.target.closest('button,a');if(!button)return;if(button.hasAttribute('data-close'))return $('#modal').close();if(button.dataset.tab){tab=button.dataset.tab;selected=null;render();return;}if(button.dataset.queue){queueMode=button.dataset.queue;render();return;}if(button.dataset.pool){rankingPool=button.dataset.pool;render();return;}if(button.dataset.filter){filter=button.dataset.filter;render();return;}if(button.dataset.game){$('#modal').close();cancelComputer();boardFlipped=false;gameId=button.dataset.game;practice=null;tab='board';render();return;}if(button.dataset.square)return squareClick(button.dataset.square);if(button.dataset.promote){$('#modal').close();return playMove(button.dataset.from,button.dataset.to,button.dataset.promote);}const a=button.dataset.action,uid=button.dataset.id;if(!a)return;
if(a==='computer')return computerForm();if(a==='quick-match')return quickMatchForm(button.dataset.mode||'free');if(a==='analysis-retry')return send('analysis_retry');if(a==='flip-board'){boardFlipped=!boardFlipped;render();return;}if(a==='undo'){if(!practice)return;cancelComputer();const c=new Chess();let n=practice.moves.length;if(practice.computer){n--;while(n>0&&n%2!==(practice.humanColor==='w'?0:1))n--;}else n--;for(const m of practice.moves.slice(0,Math.max(0,n)))c.move(m);practice.moves=practice.moves.slice(0,Math.max(0,n));practice.fen=c.fen();practice.pgn=c.pgn();practice.status='playing';practice.lastMoveAt=Date.now();selected=null;savePractice();render();computerTurn();return;}if(a==='computer-resign'){if(practice?.computer){cancelComputer();practice.status='finished';practice.result='Você desistiu · Computador venceu';savePractice();render();}return;}if(a==='resend-email')return resendEmail();if(a==='back-login')return loginForm();if(a==='resume-computer'){try{practice=JSON.parse(localStorage.getItem('arena-computer-v1'));if(!practice?.computer)return;new Chess(practice.fen);cancelComputer();practice.lastMoveAt=Date.now();tab='board';render();computerTurn();}catch{toast('Treino salvo indisponível.');}return;}if(a==='create-challenge')return challengeForm();if(a==='create-tournament')return tournamentForm();if(a==='login')return loginForm();if(a==='logout'){cancelComputer();await client.auth.signOut();session=null;loadDemo();try{state=(await api()).state;}catch{}render();return;}if(a==='profile'){if(config.configured&&!online)return loginForm();if(online){modal(`<h2>Seu perfil</h2><form id="profile-form"><label>Nome público<input name="name" minlength="2" maxlength="32" value="${name(actor.id)}" required></label><p>Rating Arena: ${state.players[actor.id]?.rating||1200}</p><button class="button primary full">Salvar nome</button></form>`);return;}modal(`<h2>Perfis de demonstração</h2><p>Troque de perfil para testar o aceite e a administração no mesmo aparelho.</p>${Object.values(state.players).map(p=>`<button class="game-row" data-action="demo-profile" data-id="${p.id}">${avatar(p.id)}${esc(p.name)}<small>${p.id==='demo-admin'?'Administrador de teste':'Jogador de teste'}</small></button>`).join('')}`);return;}if(a==='demo-profile'){actor={id:uid,admin:uid==='demo-admin'};$('#modal').close();render();return;}if(a==='practice'){cancelComputer();boardFlipped=false;practice={fen:new Chess().fen(),moves:[],pgn:'',status:'playing',white:'demo-you',black:'demo-you',whiteMs:0,blackMs:0};selected=null;tab='board';render();return;}if(a==='switch-seat'){const g=activeGame();actor={id:actor.id===g.white?g.black:g.white,admin:false};render();return;}if(a==='demo-credit')return send('demo_credit');if(a==='cancel-challenge')return send('challenge_cancel',{id:uid});if(a==='accept-challenge'){const c=state.challenges.find(c=>c.id===uid);modal(`<h2>Aceitar desafio</h2><p>Você enfrenta <b>${name(c.creator)}</b> em ${c.minutes} minutos por jogador.</p><div class="promo-line"><span>Sua entrada</span><b>${c.stake===0?'Grátis':credits(c.stake)}</b></div><div class="promo-line"><span>Total reservado</span><b>${credits(c.stake*2)}</b></div><div class="promo-line"><span>Taxa</span><b>${c.feeBps/100}%</b></div><div class="promo-line"><span>Prêmio líquido</span><b>${credits(c.stake*2-Math.floor(c.stake*2*c.feeBps/10000))}</b></div><p>Em empate, nova partida com os valores reservados. O prêmio aguarda homologação.</p><button class="button primary full" data-action="confirm-challenge" data-id="${uid}">Aceitar e reservar ${credits(c.stake)}</button>`);return;}if(a==='confirm-challenge'){if(await send('challenge_accept',{id:uid})){$('#modal').close();gameId=state.games.at(-1).id;practice=null;tab='board';render();}return;}if(a==='claim-timeout')return send('timeout',{id:uid});if(a==='game-abort')return send('game_abort',{id:uid});if(a==='game-accept')return send('game_accept',{id:uid});if(a==='draw')return send('draw',{id:uid});if(a==='resign'){modal(`<h2>Desistir da partida?</h2><p>O adversário será declarado vencedor. O resultado seguirá para homologação.</p><button class="button danger full" data-action="confirm-resign" data-id="${uid}">Confirmar desistência</button>`);return;}if(a==='confirm-resign'){if(await send('resign',{id:uid}))$('#modal').close();return;}
if(a==='join-tournament')return send('tournament_join',{id:uid});if(a==='leave-tournament')return send('tournament_leave',{id:uid});if(a==='start-tournament')return send('tournament_start',{id:uid});if(a==='cancel-tournament')return send('tournament_cancel',{id:uid});if(a==='approve-result')return send('approve_result',{id:uid});if(a==='account-status'){modal(`<h2>Conta de ${name(uid)}</h2><form id="status-form" data-user="${uid}"><label>Status<select name="status"><option value="active">Ativa (reativar)</option><option value="suspended">Suspensa</option><option value="banned">Banida</option></select></label><label>Justificativa<textarea name="reason" minlength="10" required></textarea></label><button class="button primary full">Registrar decisão</button></form>`);return;}if(a==='verify-rating'){modal(`<h2>Verificar rating</h2><form id="rating-form" data-user="${uid}"><label>Rating<input name="rating" type="number" min="100" max="3500" required></label><label>Fonte e evidências verificadas<textarea name="evidence" minlength="10" required></textarea></label><button class="button primary full">Confirmar verificação</button></form>`);return;}if(a==='report'||a==='close-review'){modal(`<h2>${a==='report'?'Denunciar partida':'Concluir revisão'}</h2><form id="reason-form" data-type="${a==='report'?'report':'review_close'}" data-id="${uid}"><label>Motivo<textarea name="reason" minlength="10" maxlength="1000" required></textarea></label><button class="button primary full">Registrar</button></form>`);return;}if(a==='reset-demo'){if(online)return toast('Esta ação é somente para dados locais.');localStorage.removeItem('arena-demo-v1');loadDemo();render();toast('Demonstração reiniciada.');return;}if(a==='export-pgn'){const g=activeGame();const url=URL.createObjectURL(new Blob([g.pgn||''],{type:'application/x-chess-pgn'}));const link=document.createElement('a');link.href=url;link.download='arena-partida.pgn';link.click();URL.revokeObjectURL(url);}
});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,d=new FormData(f);let ok=false;if(f.id==='profile-form')ok=await send('profile_update',{name:d.get('name')});if(f.id==='computer-form'){startComputer(d);$('#modal').close();return;}if(f.id==='quick-form'){if(!online){$('#modal').close();loginForm();return;}ok=await send('quick_match',{minutes:Number(d.get('minutes')),increment:Number(d.get('increment')),stake:d.get('mode')==='stake'?Math.round(Number(d.get('stake'))*100):0,currency:'TEST'});if(ok){$('#modal').close();const g=state.games.find(g=>g.status==='pending'&&[g.white,g.black].includes(actor.id));if(g){gameId=g.id;practice=null;tab='board';render();}else toast('Buscando adversário. Seu convite ficará aberto por 3 minutos.');}return;}if(f.id==='challenge-form')ok=await send('challenge_create',{stake:Math.round(Number(d.get('stake'))*100),minutes:Number(d.get('minutes')),increment:Number(d.get('increment'))});if(f.id==='settings-form')ok=await send('settings',{feeBps:Math.round(Number(d.get('fee'))*100),analysisEnabled:d.has('analysis')});if(f.id==='status-form')ok=await send('account_status',{user:f.dataset.user,status:d.get('status'),reason:d.get('reason')});if(f.id==='rating-form')ok=await send('verify_rating',{user:f.dataset.user,rating:Number(d.get('rating')),evidence:d.get('evidence')});if(f.id==='reason-form')ok=await send(f.dataset.type,{id:f.dataset.id,reason:d.get('reason')});if(f.id==='tournament-form')ok=await send('tournament_create',{name:d.get('name'),capacity:Number(d.get('capacity')),entry:Math.round(Number(d.get('entry'))*100),minRating:Number(d.get('minRating')),maxRating:Number(d.get('maxRating')),minutes:Number(d.get('minutes')),startsAt:new Date(d.get('startsAt')).getTime(),requireVerified:d.has('verified'),cameraFinal:d.has('camera')});if(f.id==='login-form'){if(!client)return;const buttons=[...f.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);const intent=e.submitter?.value,args={email:d.get('email'),password:d.get('password')};try{const result=intent==='signup'?await client.auth.signUp({...args,options:{data:{display_name:d.get('name')},emailRedirectTo:location.origin+'/'}}):await client.auth.signInWithPassword(args);if(result.error){$('#auth-error').textContent=authMessage(result.error);return;}if(!result.data.session){confirmationNotice(args.email);return;}await enterOnline(result.data.session,d.get('name'));ok=true;}catch{$('#auth-error').textContent='Não foi possível conectar. Verifique sua internet e tente novamente.';}finally{buttons.forEach(b=>b.disabled=false);}}if(ok){$('#modal').close();toast('Operação concluída.');}});
window.addEventListener('hashchange',()=>{const value=location.hash.slice(1);if(['lobby','tournaments','wallet','fairplay','ranking'].includes(value)){tab=value;render();}});
document.addEventListener('visibilitychange',()=>{const enabled=$('#privacy-toggle')?.checked;$('.board')?.classList.toggle('hidden-board',Boolean(enabled&&document.hidden));});
setInterval(updateClocks,250);
setInterval(async()=>{if(!online||document.hidden||busy)return;try{if(Date.now()-lastPresence>30000){lastPresence=Date.now();await api({id:crypto.randomUUID(),type:'presence',payload:{}});}const result=await api();if(busy||$('#modal').open)return;if(!result.actor){session=null;online=false;state=result.state;render();return;}const old=JSON.stringify(state);const added=result.state.tournaments.filter(t=>!state.tournaments.some(old=>old.id===t.id));if(added.length)toast(`${added.length} novo${added.length>1?'s campeonatos':' campeonato'} ${added.length>1?'disponíveis':'disponível'}. Confira Torneios.`);state=result.state;actor=result.actor;const pending=state.games.find(g=>g.status==='pending'&&[g.white,g.black].includes(actor.id)&&!g.accepted.includes(actor.id));if(pending&&tab!=='board'){modal(`<h2>Adversário encontrado!</h2><p>${name(pending.white===actor.id?pending.black:pending.white)} está aguardando seu aceite.</p><button class="button primary full" data-game="${pending.id}" data-close-invite>Abrir mesa e confirmar</button>`);}if(JSON.stringify(state)!==old)render();const g=state.games.find(g=>g.id===gameId);if(tab==='board'&&!practice&&g?.status==='playing'){const color=new Chess(g.fen).turn();if(g[color==='w'?'whiteMs':'blackMs']-(Date.now()-g.lastMoveAt)<=0)await send('timeout',{id:g.id});}}catch{}},2000);
async function enterOnline(currentSession,displayName){session=currentSession;online=true;const result=await api();state=result.state;actor=result.actor;if(!state.players[actor.id])await send('register',{name:displayName||session.user?.user_metadata?.display_name||'Jogador'});render();}
async function boot(){loadDemo();try{config=await fetch('/api/index?action=config').then(r=>r.json());if(config.configured){client=createClient(config.supabaseUrl,config.publishableKey);session=(await client.auth.getSession()).data.session;if(session)await enterOnline(session);else state=(await api()).state;client.auth.onAuthStateChange((event,newSession)=>{if(['SIGNED_IN','TOKEN_REFRESHED'].includes(event)&&newSession){session=newSession;setTimeout(()=>enterOnline(newSession).catch(()=>toast('Não foi possível carregar sua conta. Tente entrar novamente.')),0);}if(event==='SIGNED_OUT'){session=null;loadDemo();api().then(r=>{state=r.state;render();}).catch(()=>render());}});}}catch{}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
boot();
